// Verified Butterfly Effect levels (generated by an offline check, do not edit by hand).
// For each stage/level, `seed` makes generateLevel() build a course where:
//  • nothing moves before the first throw,
//  • pushing the first domino carries the chain all the way to the flower,
//  • `aims` throw directions (out of 221 tested) start the chain,
//  • the `example` throw was simulated end-to-end and made the flower bloom.

export type SeedInfo = {
  stage: number
  level: number
  seed: number
  aims: number
  example: [number, number]
  width: number
}

